      (1, 1188, 4, '05CBF93C', '804996937', null, '2025-10-27', '2026-02-26 10:56:39', '2025-10-27', 376, 376, 'M.O. TRABAJOS DE INGENIERIA CIVIL ***CH. 62 17/11/2025***', 1103, 146610.07, 1, 'V', 'HEM', null, null, 'STE', '2026-05-09 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2026, null, 1, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null, 0, 0, 0, 0, 0, 0, 0, 8, 2, 22401, 'E', null, null, 'S', 0, null, null),
